package com.example.expensetracker.entity;import jakarta.persistence.*;@Entity public class Expense{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; String title; Double amount; public Long getId(){return id;} public void setId(Long i){id=i;} public String getTitle(){return title;} public void setTitle(String t){title=t;} public Double getAmount(){return amount;} public void setAmount(Double a){amount=a;}}